local b=bit32.bxor
local s=string.char
local n=tonumber
local c=table.concat
local h=''
local k={106,6,47,208,122,105,165,169,136,183,142,230,215,162,163,23,249,89,161,109,50,221,237,251,224,168,73,9,46,234,133,119}
local o={}
local i=1
local p=0
while i<=#h do
 p+=1
 o[p]=s(b(n(h:sub(i,i+1),16),k[(p-1)%#k+1]))
 i+=2
end
return (loadstring or load)(c(o))()
